# Generated by build.py from recipe.yml for recipe imap-log-in-with-an-oauth-token. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--cert', 'server.pem', '--key', 'server.key', '--user', ':tok-abc123', '--mail-domain', 'example.com', '--mailbox', 'ann@example.com:annpass', '--mailbox', 'bob@example.com:bobpass', 'imaps://127.0.0.1:8080/', 'imap://127.0.0.1:8081/', 'smtp://127.0.0.1:8082/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -sS --crlf -u ann@example.com:annpass --mail-from ann@example.com --mail-rcpt ann@example.com -T hi.eml smtp://127.0.0.1:8082/example.com
try { curl.exe -sS --cacert server.pem -u ann@example.com --oauth2-bearer tok-abc123 "imaps://127.0.0.1:8080/INBOX;UID=1;SECTION=TEXT" } finally { Stop-Process $server0 }
